+    );
+
+    const metadata = await sharp(jpegBuffer).metadata();
+
+    expect(metadata.width).toBe(RECALL_BOT_IMAGE_WIDTH);
+    expect(metadata.height).toBe(RECALL_BOT_IMAGE_HEIGHT);
